import {watchPanel,mountWatch,leaveWatch} from './watch.js';
import {readingSets,listeningSets,levels,answerMatches} from './practice-library.js';
import {createPronunciation} from './pronunciation.js';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let level='all',selected={},timer=null,elapsed=0,paused=false,account='',kindNow='',answers={},zoom=1;
const $=s=>document.querySelector(s);
const audio=createPronunciation({getPreferences:()=>({accent:'en-GB',rate:Number($('#studio-rate')?.value)||1}),onError:message=>{if($('#studio-status'))$('#studio-status').textContent=message;}});
export function leaveStudio(){leaveWatch();clearInterval(timer);timer=null;audio.stop();}
function passageHTML(set){return set.passages?set.passages.map((p,pi)=>`<section><h3 id="passage-title-${pi}">Passage ${pi+1} · ${e(p.title)}</h3>${p.paragraphs.map((text,i)=>`<p id="evidence-${pi}-${i}">${e(text)}</p>`).join('')}</section>`).join(''):set.text.split('\n').map(p=>`<p>${e(p)}</p>`).join('');}
const sets=k=>k==='reading'?readingSets:listeningSets;
function key(){return 'lexora.practice.'+account+'.'+kindNow+'.'+selected[kindNow];}
function save(){try{localStorage.setItem(key(),JSON.stringify({answers,elapsed}));}catch{}}
export function studioView(kind){
 if(kind==='watch')return `<div class="page-heading"><div><h1>Watch & learn</h1><p>Tinglang. Matndan kuzating. Gapirib takrorlang.</p></div></div>${watchPanel()}`;
 const bank=sets(kind),set=bank.find(x=>x.id===selected[kind]),title=kind==='reading'?'Reading':'Listening';
 const header=`<div class="page-heading"><div><span class="eyebrow">MUSTAQIL MASHQ · A1–C1</span><h1>${title} library</h1><p>Darajangizdan boshlang. O‘z sur’atingizda mashq qiling.</p></div>${set?'<button class="btn" id="studio-back">Kutubxona</button>':''}</div>`;
 if(!set)return header+`<label class="level-filter">Daraja<select id="studio-level"><option value="all">Barcha darajalar</option>${levels.map(l=>`<option ${l===level?'selected':''}>${l}</option>`).join('')}</select></label><div class="studio-catalog">${bank.filter(s=>level==='all'||s.level===level).map(s=>`<button class="studio-choice" data-studio-id="${s.id}"><span class="tag">${s.level}</span><h2>${s.title}</h2><p>${s.format?e(s.format):s.questions.length+' savol'} · ${s.minutes} daqiqa tavsiya etiladi</p><span>Mashqni ochish</span></button>`).join('')}</div><p class="help-text">Lexora uchun yozilgan mustaqil mashqlar. Darajalar yo‘nalish beradi; bu rasmiy IELTS testi yoki CEFR sertifikati emas.</p>`;
 return header+`<div class="studio-toolbar"><span class="tag">${set.level}</span><b>${set.title}</b><output id="studio-clock" aria-label="Mashq vaqti">00:00</output><button class="btn" id="studio-pause" aria-pressed="false">Vaqtni to‘xtatish</button><label>Matn o‘lchami<select id="studio-zoom">${[1,1.15,1.3,1.5].map(n=>`<option value="${n}" ${zoom===n?'selected':''}>${Math.round(n*100)}%</option>`).join('')}</select></label></div><div class="studio-layout independent-studio" style="--reading-scale:${zoom}"><section class="studio-paper passage-pane" aria-label="${title} materiali"><h2>${set.title}</h2>${kind==='reading'?`<div class="reading-passage" id="studio-passage">${passageHTML(set)}</div><button class="btn" id="studio-highlight">Tanlangan matnni belgilash</button><button class="btn" id="studio-clear">Belgilarni tozalash</button>`:`<div class="listen-player"><button class="btn primary" id="studio-play">Tinglash</button><button class="btn" id="studio-stop">To‘xtatish</button><label>Tezlik<select id="studio-rate"><option value="0.7">0.7×</option><option value="0.85">0.85×</option><option value="1" selected>1×</option><option value="1.15">1.15×</option></select></label></div><p class="help-text">Qurilmaning inglizcha ovozi bilan o‘qiladi; studiyada yozilgan audio emas.</p><details><summary>Transcript</summary><p class="reading-passage">${e(set.text)}</p></details>`}<p id="studio-status" role="status"></p></section><section class="studio-paper questions-pane"><h2>Savollar</h2><nav class="question-map" aria-label="Savolga o‘tish">${set.questions.map((q,i)=>`<button type="button" class="btn" data-question-jump="${i}" aria-label="${i+1}-savolga o‘tish">${i+1}</button>`).join('')}</nav><form id="studio-quiz">${set.questions.map((q,i)=>`<fieldset id="practice-q${i}"><legend>${q.passage!==undefined?`<small>Passage ${q.passage+1}</small><br>`:''}${i+1}. ${e(q.prompt)}</legend>${q.options?q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" ${String(answers['q'+i])===String(j)?'checked':''} required>${e(o)}</label>`).join(''):`<label>Bir yoki ikki so‘z / raqam<input name="q${i}" value="${e(answers['q'+i]||'')}" maxlength="80" required autocomplete="off"></label>`}</fieldset>`).join('')}<div class="buttons"><button class="btn primary">Tekshirish va izohlar</button><button class="btn" id="studio-reset" type="button">Qayta boshlash</button></div><p class="help-text">Javoblar shu qurilmada saqlanadi. Guruh bahosiga ta’sir qilmaydi.</p><div id="studio-result" role="region" aria-label="Javoblar tahlili" tabindex="-1"></div></form></section></div>`;
}
export function mountStudio(kind,accountId){kindNow=kind;account=accountId||'guest';
 const draw=()=>{leaveStudio();$('#app').innerHTML=studioView(kind);mountStudio(kind,account);};
 if(kind==='watch'){mountWatch(account);return;}
 $('#studio-level')?.addEventListener('change',ev=>{level=ev.target.value;draw();});
 document.querySelectorAll('[data-studio-id]').forEach(b=>b.onclick=()=>{selected[kind]=b.dataset.studioId;answers={};elapsed=0;paused=false;try{const saved=JSON.parse(localStorage.getItem(key())||'{}');answers=saved.answers||{};elapsed=Number(saved.elapsed)||0;}catch{}draw();});
 const set=sets(kind).find(s=>s.id===selected[kind]);if(!set)return;
 $('#studio-back').onclick=()=>{save();selected[kind]=null;draw();};
 const clock=()=>{if($('#studio-clock'))$('#studio-clock').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(elapsed%60).padStart(2,'0');};clock();
 timer=setInterval(()=>{if(!paused){elapsed++;clock();if(elapsed%10===0)save();}},1000);
 $('#studio-pause').onclick=ev=>{paused=!paused;ev.target.textContent=paused?'Vaqtni davom ettirish':'Vaqtni to‘xtatish';ev.target.setAttribute('aria-pressed',String(paused));save();};
 $('#studio-zoom').onchange=ev=>{zoom=Number(ev.target.value);$('.independent-studio').style.setProperty('--reading-scale',zoom);};
 document.querySelectorAll('[data-question-jump]').forEach(b=>b.onclick=()=>{const field=$('#practice-q'+b.dataset.questionJump);field.scrollIntoView({block:'start',behavior:'smooth'});field.querySelector('input')?.focus({preventScroll:true});});
 $('#studio-quiz').onchange=ev=>{answers=Object.fromEntries(new FormData(ev.currentTarget));save();};
 $('#studio-quiz').onsubmit=ev=>{ev.preventDefault();answers=Object.fromEntries(new FormData(ev.target));save();paused=true;$('#studio-pause').textContent='Vaqtni davom ettirish';$('#studio-pause').setAttribute('aria-pressed','true');const checks=set.questions.map((q,i)=>q.options?String(q.answer)===answers['q'+i]:answerMatches(answers['q'+i],q.answer));$('#studio-result').innerHTML=`<h3>${checks.filter(Boolean).length} / ${checks.length} to‘g‘ri · ${Math.round(checks.filter(Boolean).length*100/checks.length)}%</h3><p>Har javobni matndagi dalil bilan solishtiring. Bu mashq foizi; rasmiy IELTS band bahosi emas.</p>${set.questions.map((q,i)=>`<div class="practice-explanation"><b>${checks[i]?'To‘g‘ri':'Qayta ko‘ring'} · ${i+1}</b><p>Javob: ${e(q.options?q.options[q.answer]:q.answer)}</p><p>Sizning javobingiz: ${e(q.options?q.options[Number(answers['q'+i])]??'Javobsiz':answers['q'+i]||'Javobsiz')}</p><p>${e(q.why)}</p>${q.evidence?`<blockquote>${e(q.evidence)}</blockquote><button type="button" class="btn" data-evidence="${i}">Matndagi dalilni ko‘rish · ${String.fromCharCode(65+q.paragraph)}</button>`:''}</div>`).join('')}`;$('#studio-result').focus();document.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>{const q=set.questions[Number(b.dataset.evidence)],paragraph=$('#evidence-'+q.passage+'-'+q.paragraph);if(!paragraph)return;const text=set.passages[q.passage].paragraphs[q.paragraph],index=text.indexOf(q.evidence);paragraph.innerHTML=index<0?e(text):e(text.slice(0,index))+'<mark>'+e(q.evidence)+'</mark>'+e(text.slice(index+q.evidence.length));paragraph.tabIndex=-1;paragraph.scrollIntoView({block:'center',behavior:'smooth'});paragraph.focus({preventScroll:true});});};
 $('#studio-reset').onclick=()=>{answers={};elapsed=0;paused=false;save();draw();};
 if(kind==='listening'){$('#studio-play').onclick=()=>audio.speak(set.text);$('#studio-stop').onclick=()=>audio.stop();}
 else{$('#studio-highlight').onclick=()=>{const sel=window.getSelection();if(!sel?.rangeCount||!$('#studio-passage').contains(sel.anchorNode)||!$('#studio-passage').contains(sel.focusNode)||sel.isCollapsed){$('#studio-status').textContent='Avval matndan bir parcha tanlang.';return;}const range=sel.getRangeAt(0),mark=document.createElement('mark');mark.append(range.extractContents());range.insertNode(mark);sel.removeAllRanges();$('#studio-status').textContent='Matn belgilandi.';};$('#studio-clear').onclick=()=>$('#studio-passage').querySelectorAll('mark').forEach(m=>m.replaceWith(...m.childNodes));}
}
